    static int pow(int b, long e, int mod) {
        int ans = 1;
        b %= mod;
        while (e > 0) {
            if ((e & 1) == 1)
                ans = (int) ((ans * 1L * b) % mod);
            e >>= 1;
            b = (int) ((b * 1L * b) % mod);
        }
        return ans;
    }

    static long ncr(int n, int r) {
        long ans = fac[n];
        long de = ((fac[n - r] * 1L * fac[r]) % mod);
        de = pow((int) de, mod - 2, mod);
        return (ans * de) % mod;
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        long k = sc.nextLong();
        if (k > n - 1) {
            pw.println(0);
            pw.flush();
            return;
